package com.example.rokidgeminisecretary;
import android.content.*;import android.os.*;import java.lang.reflect.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import org.json.*;
public class NavigationStopDeviceChecks {
 static int n;static void ok(boolean b){n++;if(!b)throw new AssertionError("nav stop "+n);}
 public static int run(Context c)throws Exception {n=0;CountDownLatch done=new CountDownLatch(1);AtomicReference<Throwable> error=new AtomicReference<>();new Handler(Looper.getMainLooper()).post(()->{try{MainActivity owner=new MainActivity();Method attach=ContextWrapper.class.getDeclaredMethod("attachBaseContext",Context.class);attach.setAccessible(true);attach.invoke(owner,c);c.getSharedPreferences("phone_secretary",0).edit().putString("map_route_points","[[35,139],[36,139]]").putString("map_route_destination","synthetic old target").commit();Field plan=MainActivity.class.getDeclaredField("multimodalJourney");plan.setAccessible(true);plan.set(owner,new MultimodalJourney("synthetic",new double[]{35,139},"walking","walking"));Field target=MainActivity.class.getDeclaredField("confirmedSharedDestination");target.setAccessible(true);target.set(null,"synthetic old target");Method stop=MainActivity.class.getDeclaredMethod("stopNavigationFromGlass");stop.setAccessible(true);JSONObject result=(JSONObject)stop.invoke(owner);ok(result.optBoolean("lokiNavigationStopped"));ok(result.optBoolean("suppressed"));ok(plan.get(owner)==null);ok(target.get(null).equals(""));ok(!c.getSharedPreferences("phone_secretary",0).contains("map_route_points"));ok(!c.getSharedPreferences("phone_secretary",0).contains("map_route_destination"));ok(!result.optBoolean("navigationStopped"));ok(result.optString("message").contains("ロキの案内を停止"));JSONObject repeat=(JSONObject)stop.invoke(owner);ok(repeat.optBoolean("lokiNavigationStopped"));}catch(Throwable e){error.set(e);}finally{done.countDown();}});if(!done.await(15,TimeUnit.SECONDS))throw new AssertionError("UI timeout");if(error.get()!=null)throw new AssertionError(error.get());return n;}
}
